def minRemovalDivisible(nums, p):
    n = len(nums)
    need = sum(nums) % p
    if need == 0:
        return 0
    last = {0: 0}
    r = 0
    best = n
    for j, x in enumerate(nums, 1):
        r = (r + x) % p
        i = last.get((r - need) % p)
        if i is not None and j - i < best:
            best = j - i
        last[r] = j
    return -1 if best == n else best
